<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Billiards</title>
    <style>
        :root {
            --bg: #1a1a2e;
            --surface: #252538;
            --text: #e0e0e0;
            --accent: #c9a96e;
            --btn-bg: #3a3a52;
            --btn-hover: #4e4e6a;
            --btn-text: #f0f0f0;
        }
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            background: var(--bg);
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
            overflow: hidden;
            user-select: none;
            -webkit-user-select: none;
            -webkit-tap-highlight-color: transparent;
        }
        .game-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 16px;
            background: var(--surface);
            padding: 24px 28px 20px;
            border-radius: 16px;
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
        }
        canvas {
            display: block;
            border-radius: 8px;
            cursor: crosshair;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
        }
        .controls {
            display: flex;
            align-items: center;
            gap: 20px;
            flex-wrap: wrap;
            justify-content: center;
        }
        button {
            background: var(--btn-bg);
            color: var(--btn-text);
            border: 2px solid var(--accent);
            padding: 10px 24px;
            border-radius: 8px;
            cursor: pointer;
            font-size: 15px;
            font-weight: 600;
            letter-spacing: 0.5px;
            transition: all 0.2s;
            white-space: nowrap;
        }
        button:hover {
            background: var(--btn-hover);
            box-shadow: 0 2px 12px rgba(201, 169, 110, 0.3);
        }
        button:active {
            transform: scale(0.96);
            box-shadow: 0 1px 4px rgba(201, 169, 110, 0.2);
        }
        .instructions {
            color: #b0b0b8;
            font-size: 13px;
            text-align: center;
            line-height: 1.6;
            letter-spacing: 0.3px;
        }
        .instructions strong {
            color: var(--accent);
        }
    </style>
</head>
<body>
    <div class="game-container">
        <canvas id="table" width="880" height="480"></canvas>
        <div class="controls">
            <button id="resetBtn">⟳ Rack / Reset</button>
        </div>
        <div class="instructions">
            <strong>Click &amp; drag</strong> the white cue ball <strong>backward</strong> to aim.<br>
            Longer drag = <strong>harder shot</strong>. Release to strike.
        </div>
    </div>

    <script>
        (function() {
            const canvas = document.getElementById('table');
            const ctx = canvas.getContext('2d');

            // ──────────────────── CONSTANTS ────────────────────
            const W = 800; // playfield width (physics coords)
            const H = 400; // playfield height
            const R = 12; // ball radius
            const MARGIN = 40; // canvas margin around playfield
            const POCKET_RADIUS = 20; // pocket detection radius
            const FRICTION_PER_SEC = 0.55; // speed multiplier per second
            const MIN_SPEED = 0.6; // below this, ball stops
            const WALL_RESTITUTION = 0.82;
            const BALL_RESTITUTION = 0.97;
            const MAX_SUBSTEP = 1 / 240;
            const MAX_POWER = 950; // px/sec at full drag
            const MAX_DRAG = 160; // physics pixels for max power
            const MIN_DRAG = 7; // minimum drag to shoot

            // Pocket positions in physics coordinates
            const POCKETS = [
                { x: 0, y: 0 }, { x: W / 2, y: 0 }, { x: W, y: 0 },
                { x: 0, y: H }, { x: W / 2, y: H }, { x: W, y: H },
            ];

            // Ball colors for numbered balls
            const BALL_COLORS = [
                '#FFD740', '#2979FF', '#E53935', '#7B1FA2', '#FF6D00',
                '#2E7D32', '#8B0000', '#1a1a1a', '#FFEE58', '#448AFF',
                '#F48FB1', '#B71C1C', '#66BB6A', '#1A237E', '#BF360C',
                '#FFAB00', '#00BCD4', '#795548', '#607D8B', '#CDDC39',
            ];

            function getBallColor(index) {
                return BALL_COLORS[index % BALL_COLORS.length];
            }

            function isLightColor(hex) {
                const r = parseInt(hex.slice(1, 3), 16);
                const g = parseInt(hex.slice(3, 5), 16);
                const b = parseInt(hex.slice(5, 7), 16);
                return (r * 299 + g * 587 + b * 114) / 1000 > 145;
            }

            // ──────────────────── STATE ────────────────────
            let balls = [];
            let defaultBalls = [];
            let paused = false;
            let animFrameId = null;
            let lastFrameTime = 0;

            // Aiming state
            let aiming = false;
            let aimCueBall = null;
            let aimMousePhys = { x: 0, y: 0 };
            let aimDragVec = { x: 0, y: 0 }; // vector from cue ball to mouse (drag direction)
            let cueBallOriginalPos = { x: W * 0.25, y: H / 2 };

            // ──────────────────── DEFAULT RACK ────────────────────
            function createDefaultRack() {
                const rack = [];
                // Cue ball
                rack.push({ x: W * 0.25, y: H / 2, vx: 0, vy: 0, cue: true });
                cueBallOriginalPos = { x: W * 0.25, y: H / 2 };

                // 15-ball triangle, apex at x = W*0.72, y = H/2
                const apexX = W * 0.72;
                const apexY = H / 2;
                const rowSpacing = R * Math.sqrt(3);
                const ballSpacing = 2 * R;

                for (let row = 0; row < 5; row++) {
                    const count = row + 1;
                    const x = apexX + row * rowSpacing;
                    for (let i = 0; i < count; i++) {
                        const y = apexY - (count - 1) * ballSpacing / 2 + i * ballSpacing;
                        rack.push({ x, y, vx: 0, vy: 0, cue: false });
                    }
                }
                return rack;
            }

            defaultBalls = createDefaultRack();
            balls = defaultBalls.map(b => ({ ...b, vx: b.vx || 0, vy: b.vy || 0, potted: false }));

            // ──────────────────── PHYSICS ────────────────────
            function vecLen(x, y) { return Math.sqrt(x * x + y * y); }

            function findCueBall() {
                for (let i = 0; i < balls.length; i++) {
                    if (balls[i].cue && !balls[i].potted) return i;
                }
                return -1;
            }

            function stepPhysics(dt) {
                if (dt <= 0) return;
                let remaining = dt;
                while (remaining > 1e-9) {
                    const subDt = Math.min(remaining, MAX_SUBSTEP);
                    remaining -= subDt;
                    substepPhysics(subDt);
                }
            }

            function substepPhysics(dt) {
                // 1. Move balls
                for (let i = 0; i < balls.length; i++) {
                    const b = balls[i];
                    if (b.potted) continue;
                    b.x += b.vx * dt;
                    b.y += b.vy * dt;
                }

                // 2. Check pockets
                for (let i = 0; i < balls.length; i++) {
                    const b = balls[i];
                    if (b.potted) continue;
                    for (const pk of POCKETS) {
                        const dx = b.x - pk.x;
                        const dy = b.y - pk.y;
                        if (vecLen(dx, dy) < POCKET_RADIUS) {
                            b.potted = true;
                            b.vx = 0;
                            b.vy = 0;
                            break;
                        }
                    }
                }

                // 3. Cushion collisions (only for non-potted balls)
                for (let i = 0; i < balls.length; i++) {
                    const b = balls[i];
                    if (b.potted) continue;

                    // Check if ball is near a pocket — if so, skip cushion for that edge
                    let nearPocketX = false;
                    let nearPocketY = false;
                    for (const pk of POCKETS) {
                        const dx = b.x - pk.x;
                        const dy = b.y - pk.y;
                        if (vecLen(dx, dy) < POCKET_RADIUS + R) {
                            // Ball overlaps pocket zone; skip relevant cushion
                            if (Math.abs(pk.x - 0) < 1 || Math.abs(pk.x - W) < 1) nearPocketX = true;
                            if (Math.abs(pk.y - 0) < 1 || Math.abs(pk.y - H) < 1) nearPocketY = true;
                            if (Math.abs(pk.x - W / 2) < 1 && (Math.abs(pk.y - 0) < 1 || Math.abs(pk.y - H) < 1))
                                nearPocketY = true;
                        }
                    }

                    // Left wall
                    if (b.x < R && !nearPocketX) {
                        b.x = R;
                        b.vx = Math.abs(b.vx) * WALL_RESTITUTION;
                    }
                    // Right wall
                    if (b.x > W - R && !nearPocketX) {
                        b.x = W - R;
                        b.vx = -Math.abs(b.vx) * WALL_RESTITUTION;
                    }
                    // Top wall
                    if (b.y < R && !nearPocketY) {
                        b.y = R;
                        b.vy = Math.abs(b.vy) * WALL_RESTITUTION;
                    }
                    // Bottom wall
                    if (b.y > H - R && !nearPocketY) {
                        b.y = H - R;
                        b.vy = -Math.abs(b.vy) * WALL_RESTITUTION;
                    }

                    // Also clamp to absolute bounds in case of pocket-adjacent escapes
                    b.x = Math.max(R, Math.min(W - R, b.x));
                    b.y = Math.max(R, Math.min(H - R, b.y));
                }

                // 4. Ball-ball collisions
                for (let i = 0; i < balls.length; i++) {
                    if (balls[i].potted) continue;
                    for (let j = i + 1; j < balls.length; j++) {
                        if (balls[j].potted) continue;
                        const bi = balls[i];
                        const bj = balls[j];
                        const dx = bj.x - bi.x;
                        const dy = bj.y - bi.y;
                        const dist = vecLen(dx, dy);
                        const minDist = 2 * R;
                        if (dist < minDist && dist > 1e-9) {
                            // Normal from i to j
                            const nx = dx / dist;
                            const ny = dy / dist;

                            // Relative velocity along normal
                            const dvx = bi.vx - bj.vx;
                            const dvy = bi.vy - bj.vy;
                            const vrn = dvx * nx + dvy * ny;

                            if (vrn > 0) {
                                // Impulse magnitude (equal mass, with restitution)
                                const imp = vrn * (1 + BALL_RESTITUTION) / 2;
                                bi.vx -= imp * nx;
                                bi.vy -= imp * ny;
                                bj.vx += imp * nx;
                                bj.vy += imp * ny;
                            }

                            // Separate overlapping balls
                            const overlap = minDist - dist;
                            const sepX = nx * overlap / 2;
                            const sepY = ny * overlap / 2;
                            bi.x -= sepX;
                            bi.y -= sepY;
                            bj.x += sepX;
                            bj.y += sepY;
                        }
                    }
                }

                // 5. Friction
                const frictionFactor = Math.pow(FRICTION_PER_SEC, dt);
                for (let i = 0; i < balls.length; i++) {
                    const b = balls[i];
                    if (b.potted) continue;
                    b.vx *= frictionFactor;
                    b.vy *= frictionFactor;
                    const speed = vecLen(b.vx, b.vy);
                    if (speed < MIN_SPEED) {
                        b.vx = 0;
                        b.vy = 0;
                    }
                }
            }

            // ──────────────────── RENDERING ────────────────────
            function toCanvasX(px) { return px + MARGIN; }

            function toCanvasY(py) { return py + MARGIN; }

            function draw() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                // Outer rail (dark wood)
                ctx.fillStyle = '#4E342E';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                // Rail bevel outer
                ctx.fillStyle = '#6D4C41';
                ctx.fillRect(2, 2, canvas.width - 4, canvas.height - 4);

                // Felt
                const feltX = MARGIN;
                const feltY = MARGIN;
                const feltW = W;
                const feltH = H;
                ctx.fillStyle = '#2E7D32';
                ctx.fillRect(feltX, feltY, feltW, feltH);

                // Felt texture (subtle gradient)
                const feltGrad = ctx.createRadialGradient(
                    feltX + feltW / 2, feltY + feltH / 2, feltW * 0.4,
                    feltX + feltW / 2, feltY + feltH / 2, feltW * 0.85
                );
                feltGrad.addColorStop(0, 'rgba(255,255,255,0.04)');
                feltGrad.addColorStop(1, 'rgba(0,0,0,0.06)');
                ctx.fillStyle = feltGrad;
                ctx.fillRect(feltX, feltY, feltW, feltH);

                // Inner rail edge shadow
                ctx.strokeStyle = '#3E2723';
                ctx.lineWidth = 4;
                ctx.strokeRect(feltX - 1, feltY - 1, feltW + 2, feltH + 2);
                ctx.strokeStyle = '#5D4037';
                ctx.lineWidth = 2;
                ctx.strokeRect(feltX + 1, feltY + 1, feltW - 2, feltH - 2);

                // Draw pockets
                for (const pk of POCKETS) {
                    const cx = toCanvasX(pk.x);
                    const cy = toCanvasY(pk.y);
                    // Pocket shadow
                    const pocketGrad = ctx.createRadialGradient(cx, cy, POCKET_RADIUS * 0.4, cx, cy, POCKET_RADIUS);
                    pocketGrad.addColorStop(0, '#050505');
                    pocketGrad.addColorStop(0.7, '#0a0a0a');
                    pocketGrad.addColorStop(1, '#1a1008');
                    ctx.fillStyle = pocketGrad;
                    ctx.beginPath();
                    ctx.arc(cx, cy, POCKET_RADIUS, 0, Math.PI * 2);
                    ctx.fill();
                    // Pocket rim
                    ctx.strokeStyle = '#2a1a0c';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }

                // Draw balls
                for (let i = 0; i < balls.length; i++) {
                    const b = balls[i];
                    if (b.potted) continue;
                    const cx = toCanvasX(b.x);
                    const cy = toCanvasY(b.y);

                    if (b.cue) {
                        // Cue ball — white with subtle shine
                        const cueGrad = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.35, R * 0.1, cx, cy, R);
                        cueGrad.addColorStop(0, '#ffffff');
                        cueGrad.addColorStop(0.6, '#f0f0f0');
                        cueGrad.addColorStop(1, '#d0d0d0');
                        ctx.fillStyle = cueGrad;
                        ctx.beginPath();
                        ctx.arc(cx, cy, R, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.strokeStyle = '#b0b0b0';
                        ctx.lineWidth = 1;
                        ctx.stroke();
                        // Small red dot (cue mark)
                        ctx.fillStyle = '#cc3333';
                        ctx.beginPath();
                        ctx.arc(cx, cy, R * 0.22, 0, Math.PI * 2);
                        ctx.fill();
                    } else {
                        // Numbered ball
                        const color = getBallColor(i);
                        const ballGrad = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.35, R * 0.08, cx, cy, R);
                        ballGrad.addColorStop(0, '#ffffff');
                        ballGrad.addColorStop(0.25, color);
                        ballGrad.addColorStop(1, '#000000');
                        ctx.fillStyle = ballGrad;
                        ctx.beginPath();
                        ctx.arc(cx, cy, R, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.strokeStyle = 'rgba(0,0,0,0.5)';
                        ctx.lineWidth = 1;
                        ctx.stroke();

                        // White number circle
                        const numRadius = R * 0.58;
                        ctx.fillStyle = '#fafafa';
                        ctx.beginPath();
                        ctx.arc(cx, cy, numRadius, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                        ctx.lineWidth = 0.7;
                        ctx.stroke();

                        // Number text
                        const num = (i + 1).toString();
                        const fontSize = num.length > 1 ? R * 0.78 : R * 0.9;
                        ctx.fillStyle = '#111111';
                        ctx.font = `bold ${fontSize}px 'Segoe UI', Arial, sans-serif`;
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(num, cx, cy + 0.5);
                    }
                }

                // Draw aim line and cue stick
                if (aiming && aimCueBall && !aimCueBall.potted) {
                    const cx = toCanvasX(aimCueBall.x);
                    const cy = toCanvasY(aimCueBall.y);
                    const dragDist = vecLen(aimDragVec.x, aimDragVec.y);

                    if (dragDist > MIN_DRAG) {
                        // Shot direction = opposite of drag
                        const shotDirX = -aimDragVec.x / dragDist;
                        const shotDirY = -aimDragVec.y / dragDist;
                        const power = Math.min(dragDist / MAX_DRAG, 1);
                        const lineLen = power * 200; // visual line length

                        // Aim line (forward)
                        const endX = cx + shotDirX * lineLen;
                        const endY = cy + shotDirY * lineLen;

                        // Power-based color
                        const r = Math.floor(255 * power);
                        const g = Math.floor(255 * (1 - power));
                        const b = Math.floor(50 * (1 - power));
                        ctx.strokeStyle = `rgb(${r},${g},${b})`;
                        ctx.lineWidth = 2.5;
                        ctx.setLineDash([8, 4]);
                        ctx.beginPath();
                        ctx.moveTo(cx, cy);
                        ctx.lineTo(endX, endY);
                        ctx.stroke();
                        ctx.setLineDash([]);

                        // Arrowhead
                        const arrowSize = 10 + power * 6;
                        const ax = endX;
                        const ay = endY;
                        const perpX = -shotDirY;
                        const perpY = shotDirX;
                        ctx.fillStyle = `rgb(${r},${g},${b})`;
                        ctx.beginPath();
                        ctx.moveTo(ax, ay);
                        ctx.lineTo(ax - shotDirX * arrowSize + perpX * arrowSize * 0.5,
                            ay - shotDirY * arrowSize + perpY * arrowSize * 0.5);
                        ctx.lineTo(ax - shotDirX * arrowSize - perpX * arrowSize * 0.5,
                            ay - shotDirY * arrowSize - perpY * arrowSize * 0.5);
                        ctx.closePath();
                        ctx.fill();

                        // Cue stick (behind, in drag direction)
                        const stickBackX = cx + aimDragVec.x / dragDist * dragDist;
                        const stickBackY = cy + aimDragVec.y / dragDist * dragDist;
                        const stickTipX = cx - aimDragVec.x / dragDist * R;
                        const stickTipY = cy - aimDragVec.y / dragDist * R;

                        ctx.strokeStyle = '#8B5E3C';
                        ctx.lineWidth = 3.5;
                        ctx.lineCap = 'round';
                        ctx.beginPath();
                        ctx.moveTo(stickTipX, stickTipY);
                        ctx.lineTo(stickBackX, stickBackY);
                        ctx.stroke();
                        ctx.lineCap = 'butt';

                        // Cue tip
                        ctx.fillStyle = '#f5f5f5';
                        ctx.beginPath();
                        ctx.arc(stickTipX, stickTipY, 2.5, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.strokeStyle = '#555';
                        ctx.lineWidth = 1;
                        ctx.stroke();
                    }
                }
            }

            // ──────────────────── API: window.sim ────────────────────
            window.sim = {
                W,
                H,
                R,

                reset(newBalls) {
                    balls = newBalls.map(b => ({
                        x: b.x,
                        y: b.y,
                        vx: b.vx || 0,
                        vy: b.vy || 0,
                        cue: !!b.cue,
                        potted: false,
                    }));
                    // Update cue ball original position
                    for (const b of balls) {
                        if (b.cue) {
                            cueBallOriginalPos = { x: b.x, y: b.y };
                            break;
                        }
                    }
                    // Also store as default for the reset button
                    defaultBalls = newBalls.map(b => ({
                        x: b.x,
                        y: b.y,
                        vx: b.vx || 0,
                        vy: b.vy || 0,
                        cue: !!b.cue,
                    }));
                    aiming = false;
                    aimCueBall = null;
                    draw();
                },

                step(dt) {
                    if (dt > 0) {
                        stepPhysics(dt);
                    }
                    draw();
                },

                state() {
                    return balls.map(b => ({
                        x: b.x,
                        y: b.y,
                        vx: b.vx,
                        vy: b.vy,
                        potted: b.potted,
                        cue: b.cue,
                    }));
                },

                shoot(vx, vy) {
                    const ci = findCueBall();
                    if (ci >= 0) {
                        balls[ci].vx = vx;
                        balls[ci].vy = vy;
                    }
                },

                pause() {
                    paused = true;
                },

                resume() {
                    paused = false;
                    lastFrameTime = 0;
                },
            };

            // ──────────────────── MOUSE INTERACTION ────────────────────
            function getPhysicsCoords(e) {
                const rect = canvas.getBoundingClientRect();
                const scaleX = canvas.width / rect.width;
                const scaleY = canvas.height / rect.height;
                const cx = (e.clientX - rect.left) * scaleX;
                const cy = (e.clientY - rect.top) * scaleY;
                return { x: cx - MARGIN, y: cy - MARGIN };
            }

            function getCueBallForAiming() {
                const ci = findCueBall();
                if (ci < 0) return null;
                const cb = balls[ci];
                const speed = vecLen(cb.vx, cb.vy);
                if (speed > 2) return null; // cue ball is moving
                return cb;
            }

            canvas.addEventListener('mousedown', function(e) {
                if (e.button !== 0) return;
                const phys = getPhysicsCoords(e);
                const cb = getCueBallForAiming();

                if (!cb) {
                    // Cue ball potted or moving — try to respawn if potted
                    const ci = findCueBall();
                    if (ci < 0) {
                        // All cue balls potted? Find any cue ball in the array
                        for (let i = 0; i < balls.length; i++) {
                            if (balls[i].cue) {
                                balls[i].potted = false;
                                balls[i].x = cueBallOriginalPos.x;
                                balls[i].y = cueBallOriginalPos.y;
                                balls[i].vx = 0;
                                balls[i].vy = 0;
                                // Nudge overlapping balls
                                for (let j = 0; j < balls.length; j++) {
                                    if (i !== j && !balls[j].potted) {
                                        const dx = balls[j].x - balls[i].x;
                                        const dy = balls[j].y - balls[i].y;
                                        const dist = vecLen(dx, dy);
                                        if (dist < 2 * R && dist > 1e-6) {
                                            const nx = dx / dist;
                                            const ny = dy / dist;
                                            balls[j].x += nx * (2 * R - dist + 1);
                                            balls[j].y += ny * (2 * R - dist + 1);
                                        } else if (dist < 1e-6) {
                                            balls[j].x += 2 * R + 1;
                                        }
                                    }
                                }
                                draw();
                                return;
                            }
                        }
                    }
                    return;
                }

                // Check if click is near the cue ball
                const dx = phys.x - cb.x;
                const dy = phys.y - cb.y;
                const dist = vecLen(dx, dy);
                if (dist < R * 2.5) {
                    aiming = true;
                    aimCueBall = cb;
                    aimMousePhys = phys;
                    aimDragVec = { x: phys.x - cb.x, y: phys.y - cb.y };
                    canvas.style.cursor = 'grabbing';
                    draw();
                }
            });

            canvas.addEventListener('mousemove', function(e) {
                if (!aiming || !aimCueBall || aimCueBall.potted) return;
                const phys = getPhysicsCoords(e);
                aimMousePhys = phys;
                aimDragVec = { x: phys.x - aimCueBall.x, y: phys.y - aimCueBall.y };
                draw();
            });

            canvas.addEventListener('mouseup', function(e) {
                if (!aiming) return;
                aiming = false;
                canvas.style.cursor = 'crosshair';

                if (aimCueBall && !aimCueBall.potted) {
                    const dragDist = vecLen(aimDragVec.x, aimDragVec.y);
                    if (dragDist > MIN_DRAG) {
                        const power = Math.min(dragDist / MAX_DRAG, 1);
                        const shotSpeed = power * MAX_POWER;
                        const shotDirX = -aimDragVec.x / dragDist;
                        const shotDirY = -aimDragVec.y / dragDist;
                        aimCueBall.vx = shotDirX * shotSpeed;
                        aimCueBall.vy = shotDirY * shotSpeed;
                    }
                }
                aimCueBall = null;
                draw();
            });

            canvas.addEventListener('mouseleave', function() {
                if (aiming) {
                    aiming = false;
                    aimCueBall = null;
                    canvas.style.cursor = 'crosshair';
                    draw();
                }
            });

            // Touch support
            canvas.addEventListener('touchstart', function(e) {
                if (e.touches.length === 1) {
                    e.preventDefault();
                    const touch = e.touches[0];
                    const phys = getPhysicsCoords(touch);
                    const cb = getCueBallForAiming();

                    if (!cb) {
                        const ci = findCueBall();
                        if (ci < 0) {
                            for (let i = 0; i < balls.length; i++) {
                                if (balls[i].cue) {
                                    balls[i].potted = false;
                                    balls[i].x = cueBallOriginalPos.x;
                                    balls[i].y = cueBallOriginalPos.y;
                                    balls[i].vx = 0;
                                    balls[i].vy = 0;
                                    for (let j = 0; j < balls.length; j++) {
                                        if (i !== j && !balls[j].potted) {
                                            const dx = balls[j].x - balls[i].x;
                                            const dy = balls[j].y - balls[i].y;
                                            const dist = vecLen(dx, dy);
                                            if (dist < 2 * R && dist > 1e-6) {
                                                const nx = dx / dist;
                                                const ny = dy / dist;
                                                balls[j].x += nx * (2 * R - dist + 1);
                                                balls[j].y += ny * (2 * R - dist + 1);
                                            } else if (dist < 1e-6) {
                                                balls[j].x += 2 * R + 1;
                                            }
                                        }
                                    }
                                    draw();
                                    return;
                                }
                            }
                        }
                        return;
                    }
                    const dx = phys.x - cb.x;
                    const dy = phys.y - cb.y;
                    const dist = vecLen(dx, dy);
                    if (dist < R * 2.5) {
                        aiming = true;
                        aimCueBall = cb;
                        aimMousePhys = phys;
                        aimDragVec = { x: phys.x - cb.x, y: phys.y - cb.y };
                        draw();
                    }
                }
            }, { passive: false });

            canvas.addEventListener('touchmove', function(e) {
                if (!aiming || !aimCueBall || aimCueBall.potted) return;
                e.preventDefault();
                if (e.touches.length === 1) {
                    const phys = getPhysicsCoords(e.touches[0]);
                    aimMousePhys = phys;
                    aimDragVec = { x: phys.x - aimCueBall.x, y: phys.y - aimCueBall.y };
                    draw();
                }
            }, { passive: false });

            canvas.addEventListener('touchend', function(e) {
                if (!aiming) return;
                aiming = false;
                if (aimCueBall && !aimCueBall.potted) {
                    const dragDist = vecLen(aimDragVec.x, aimDragVec.y);
                    if (dragDist > MIN_DRAG) {
                        const power = Math.min(dragDist / MAX_DRAG, 1);
                        const shotSpeed = power * MAX_POWER;
                        const shotDirX = -aimDragVec.x / dragDist;
                        const shotDirY = -aimDragVec.y / dragDist;
                        aimCueBall.vx = shotDirX * shotSpeed;
                        aimCueBall.vy = shotDirY * shotSpeed;
                    }
                }
                aimCueBall = null;
                draw();
            });

            // ──────────────────── RESET BUTTON ────────────────────
            document.getElementById('resetBtn').addEventListener('click', function() {
                window.sim.reset(defaultBalls);
                aiming = false;
                aimCueBall = null;
                canvas.style.cursor = 'crosshair';
                draw();
            });

            // ──────────────────── ANIMATION LOOP ────────────────────
            function animate(timestamp) {
                if (!lastFrameTime) lastFrameTime = timestamp;
                let dt = (timestamp - lastFrameTime) / 1000;
                lastFrameTime = timestamp;

                if (dt > 0.05) dt = 0.05; // cap at ~20fps to avoid jumps
                if (dt <= 0) dt = 1 / 120;

                if (!paused) {
                    // Don't step physics for the cue ball while aiming
                    if (aiming && aimCueBall && !aimCueBall.potted) {
                        // Save cue ball velocity, zero it during aiming, step, then restore
                        const savedVx = aimCueBall.vx;
                        const savedVy = aimCueBall.vy;
                        aimCueBall.vx = 0;
                        aimCueBall.vy = 0;
                        stepPhysics(dt);
                        aimCueBall.vx = savedVx;
                        aimCueBall.vy = savedVy;
                    } else {
                        stepPhysics(dt);
                    }
                    draw();
                }

                // Auto-respawn potted cue ball if all balls are stopped
                if (!aiming) {
                    const ci = findCueBall();
                    if (ci < 0) {
                        // Cue ball is potted, check if all others are stopped
                        let allStopped = true;
                        for (const b of balls) {
                            if (!b.potted && vecLen(b.vx, b.vy) > MIN_SPEED) {
                                allStopped = false;
                                break;
                            }
                        }
                        if (allStopped) {
                            // Respawn cue ball
                            for (let i = 0; i < balls.length; i++) {
                                if (balls[i].cue) {
                                    balls[i].potted = false;
                                    balls[i].x = cueBallOriginalPos.x;
                                    balls[i].y = cueBallOriginalPos.y;
                                    balls[i].vx = 0;
                                    balls[i].vy = 0;
                                    // Nudge overlapping balls
                                    for (let j = 0; j < balls.length; j++) {
                                        if (i !== j && !balls[j].potted) {
                                            const dx = balls[j].x - balls[i].x;
                                            const dy = balls[j].y - balls[i].y;
                                            const dist = vecLen(dx, dy);
                                            if (dist < 2 * R && dist > 1e-6) {
                                                const nx = dx / dist;
                                                const ny = dy / dist;
                                                balls[j].x += nx * (2 * R - dist + 1);
                                                balls[j].y += ny * (2 * R - dist + 1);
                                            } else if (dist < 1e-6) {
                                                balls[j].x += 2 * R + 1;
                                            }
                                        }
                                    }
                                    draw();
                                    break;
                                }
                            }
                        }
                    }
                }

                animFrameId = requestAnimationFrame(animate);
            }

            // ──────────────────── INITIALIZATION ────────────────────
            function init() {
                balls = defaultBalls.map(b => ({
                    ...b,
                    vx: b.vx || 0,
                    vy: b.vy || 0,
                    potted: false,
                }));
                for (const b of balls) {
                    if (b.cue) {
                        cueBallOriginalPos = { x: b.x, y: b.y };
                        break;
                    }
                }
                aiming = false;
                aimCueBall = null;
                paused = false;
                lastFrameTime = 0;
                canvas.style.cursor = 'crosshair';
                draw();
                if (animFrameId) cancelAnimationFrame(animFrameId);
                animFrameId = requestAnimationFrame(animate);
            }

            init();

            // Handle page visibility (pause when hidden)
            document.addEventListener('visibilitychange', function() {
                if (document.hidden) {
                    lastFrameTime = 0;
                }
            });

            console.log('🎱 Billiards ready. window.sim available for programmatic control.');
            console.log('   sim.W =', W, ' sim.H =', H, ' sim.R =', R);
            console.log('   API: sim.reset(balls) | sim.step(dt) | sim.state() | sim.shoot(vx,vy) | sim.pause() | sim.resume()');
        })();
    </script>
</body>
</html>
